def build(words):
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})   # make the child if missing
        node['$'] = True                     # end-of-word mark
    return root

def has_prefix(root, p):
    node = root
    for ch in p:
        if ch not in node:
            return False
        node = node[ch]
    return True

trie = build(["car", "cat", "dog"])
print(has_prefix(trie, "ca"), has_prefix(trie, "cow"))  # -> True False

