def slow(words, queries):          # brute force: scan every word per query, O(Q * N * L)
    return [sum(w.startswith(q) for w in words) for q in queries]

def fast(words, queries):          # trie with a count per node, O(total letters)
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {'#': 0})
            node['#'] += 1         # one more word passes through here
    out = []
    for q in queries:
        node = root
        for ch in q:
            node = node.get(ch)
            if node is None:       # no word has this prefix
                break
        out.append(node['#'] if node else 0)
    return out

words = ["apple", "app", "apt", "bat"]
for queries in [["ap", "app", "b"], ["c", "apples"]]:
    print(slow(words, queries), fast(words, queries))  # -> [3, 2, 1] [3, 2, 1], then [0, 0] [0, 0]
